var svcProject = projects.FirstOrDefault(p => p.Name == "Services.csproj");
if (svcProject != null)
{
    var pkgRefs = svcProject.FindChildrenRecursive<Item>()
        .Where(i => i.Name == "PackageReference" || i.Name == "Reference")
        .ToList();
    foreach (var r in pkgRefs)
        Console.WriteLine($"  {r.Name}: {r.Text}");
}
EOF
